mapper.select:
SELECT n.*, u.real_name AS author_name, c.course_name, m.major_name,
       t.real_name AS recommend_teacher_name
FROM study_note n
LEFT JOIN sys_user u ON n.author_id = u.id
LEFT JOIN sys_course c ON n.course_id = c.id
LEFT JOIN sys_major m ON n.major_id = m.id
LEFT JOIN sys_user t ON n.recommend_teacher_id = t.id
WHERE n.deleted = 0

    AND (n.title LIKE CONCAT('%',#{keyword},'%') OR n.description LIKE CONCAT('%',#{keyword},'%'))

AND n.course_id = #{courseId}
AND n.major_id = #{majorId}
AND n.grade = #{grade}
AND n.note_type = #{noteType}
AND n.is_free = #{isFree}
AND n.status = #{status}
AND n.status = 'PUBLISHED'
AND n.author_id = #{authorId}
AND n.is_recommended = 1

    ORDER BY n.avg_rating DESC, n.rating_count DESC
    ORDER BY n.download_count DESC
    ORDER BY n.view_count DESC
    ORDER BY n.create_time DESC
